import type { RecoveryRecord, RecoveryStore } from './types';

/** Record ids and file keys are generated by Folio; anything else is refused. */
const SAFE_NAME = /^[A-Za-z0-9_-]{1,128}$/;

function assertName(kind: string, value: string): void {
  if (!SAFE_NAME.test(value)) throw new Error(`Invalid recovery ${kind}.`);
}

interface StoredRecord {
  id: string;
  title: string;
  savedAt: string;
  snapshot: string;
}

const encoder = new TextEncoder();

/** A recovery store that lives in memory (tests, or browsers without IndexedDB). */
export function createMemoryRecoveryStore(): RecoveryStore & {
  records: Map<string, StoredRecord>;
  files: Map<string, Map<string, Uint8Array>>;
} {
  const records = new Map<string, StoredRecord>();
  const files = new Map<string, Map<string, Uint8Array>>();
  const sizeOf = (id: string) => {
    let total = encoder.encode(records.get(id)?.snapshot ?? '').byteLength;
    for (const bytes of files.get(id)?.values() ?? []) total += bytes.byteLength;
    return total;
  };
  return {
    records,
    files,
    async list() {
      return [...records.values()]
        .map((record): RecoveryRecord => ({
          id: record.id,
          title: record.title,
          savedAt: record.savedAt,
          byteLength: sizeOf(record.id),
        }))
        .sort((a, b) => b.savedAt.localeCompare(a.savedAt));
    },
    async saveSnapshot({ id, title }, snapshot) {
      assertName('id', id);
      records.set(id, { id, title, savedAt: new Date().toISOString(), snapshot });
    },
    async saveFile(id, key, bytes) {
      assertName('id', id);
      assertName('file key', key);
      let entries = files.get(id);
      if (!entries) files.set(id, (entries = new Map()));
      if (!entries.has(key)) entries.set(key, bytes.slice());
    },
    async hasFile(id, key) {
      return files.get(id)?.has(key) ?? false;
    },
    async load(id) {
      const record = records.get(id);
      if (!record) return null;
      const stored = files.get(id) ?? new Map<string, Uint8Array>();
      return {
        snapshot: record.snapshot,
        files: new Map([...stored].map(([key, bytes]) => [key, bytes.slice()])),
      };
    },
    async remove(id) {
      records.delete(id);
      files.delete(id);
    },
  };
}

const RECORDS = 'records';
const FILES = 'files';

function request<T>(req: IDBRequest<T>): Promise<T> {
  return new Promise((resolve, reject) => {
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error ?? new Error('IndexedDB request failed.'));
  });
}

function done(transaction: IDBTransaction): Promise<void> {
  return new Promise((resolve, reject) => {
    transaction.oncomplete = () => resolve();
    transaction.onabort = () => reject(transaction.error ?? new Error('IndexedDB aborted.'));
    transaction.onerror = () => reject(transaction.error ?? new Error('IndexedDB failed.'));
  });
}

/**
 * Recovery data in IndexedDB (browsers and the extension). Files are stored
 * per record under `[recordId, key]`, so removing a record removes its files.
 */
export function createIndexedDbRecoveryStore(
  name = 'folio-recovery',
  factory: IDBFactory | undefined = globalThis.indexedDB,
): RecoveryStore {
  if (!factory) return createMemoryRecoveryStore();
  let opening: Promise<IDBDatabase> | null = null;
  const open = () =>
    (opening ??= new Promise<IDBDatabase>((resolve, reject) => {
      const req = factory.open(name, 1);
      req.onupgradeneeded = () => {
        const db = req.result;
        if (!db.objectStoreNames.contains(RECORDS))
          db.createObjectStore(RECORDS, { keyPath: 'id' });
        if (!db.objectStoreNames.contains(FILES)) {
          db.createObjectStore(FILES, { keyPath: ['id', 'key'] }).createIndex('byRecord', 'id');
        }
      };
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => {
        opening = null;
        reject(req.error ?? new Error('IndexedDB is unavailable.'));
      };
    }));

  const fileRange = (id: string) => IDBKeyRange.only(id);

  return {
    async list() {
      const db = await open();
      const tx = db.transaction([RECORDS, FILES], 'readonly');
      const records = await request<StoredRecord[]>(tx.objectStore(RECORDS).getAll());
      const files = await request<Array<{ id: string; bytes: Uint8Array }>>(
        tx.objectStore(FILES).getAll(),
      );
      const sizes = new Map<string, number>();
      for (const file of files) {
        sizes.set(file.id, (sizes.get(file.id) ?? 0) + file.bytes.byteLength);
      }
      return records
        .map((record) => ({
          id: record.id,
          title: record.title,
          savedAt: record.savedAt,
          byteLength: encoder.encode(record.snapshot).byteLength + (sizes.get(record.id) ?? 0),
        }))
        .sort((a, b) => b.savedAt.localeCompare(a.savedAt));
    },
    async saveSnapshot({ id, title }, snapshot) {
      assertName('id', id);
      const db = await open();
      const tx = db.transaction(RECORDS, 'readwrite');
      tx.objectStore(RECORDS).put({
        id,
        title,
        savedAt: new Date().toISOString(),
        snapshot,
      } satisfies StoredRecord);
      await done(tx);
    },
    async saveFile(id, key, bytes) {
      assertName('id', id);
      assertName('file key', key);
      const db = await open();
      const tx = db.transaction(FILES, 'readwrite');
      const store = tx.objectStore(FILES);
      const existing = await request(store.getKey([id, key]));
      if (existing === undefined) store.put({ id, key, bytes: bytes.slice() });
      await done(tx);
    },
    async hasFile(id, key) {
      const db = await open();
      const tx = db.transaction(FILES, 'readonly');
      return (await request(tx.objectStore(FILES).getKey([id, key]))) !== undefined;
    },
    async load(id) {
      const db = await open();
      const tx = db.transaction([RECORDS, FILES], 'readonly');
      const record = await request<StoredRecord | undefined>(tx.objectStore(RECORDS).get(id));
      if (!record) return null;
      const files = await request<Array<{ key: string; bytes: Uint8Array }>>(
        tx.objectStore(FILES).index('byRecord').getAll(fileRange(id)),
      );
      return { snapshot: record.snapshot, files: new Map(files.map((f) => [f.key, f.bytes])) };
    },
    async remove(id) {
      const db = await open();
      const tx = db.transaction([RECORDS, FILES], 'readwrite');
      tx.objectStore(RECORDS).delete(id);
      const files = tx.objectStore(FILES);
      const keys = await request(files.index('byRecord').getAllKeys(fileRange(id)));
      for (const key of keys) files.delete(key);
      await done(tx);
    },
  };
}
